Arguments: {"code":"const tabId = 787783793;
const ranking = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll("section.search-result, .card, li.search-results__list__item, div.search-result"));
  const results = [];
  const seen = new Set();

  cards.forEach(c => {
    const text = c.innerText;
    const match = text.match(/#(\d+)\s+Best Boarding High Schools in America\s*\n+([^\n]+)\s*\n+([^\n]+)/);
    if (match) {
      const rank = parseInt(match[1], 10);
      const name = match[2].trim();
      const location = match[3].trim();
      if (!seen.has(name)) {
        seen.add(name);
        results.push({ rank, name, location });
      }
    }
  });
  return results.sort((a, b) => a.rank - b.rank);
});

console.log("Extracted rankings:", ranking.length, ranking);
","cwd":null,"title":"Extract top boarding school list from Niche"}
